14	fn main() {
15	    let args: Vec<String> = std::env::args().collect();
16	    if args.iter().any(|a| a == "-V" || a == "--version") {
17	        version::print();
18	        return;
19	    }
20	    if connect_repl::try_dispatch_args(&args) {
21	        return;
22	    }
23	    let flag = |name: &str| -> Option<String> {
24	        args.iter()
25	            .position(|a| a == name)
26	            .and_then(|p| args.get(p + 1))
27	            .cloned()
28	    };
29	    let mut env = Environment::new();
30	    let trace_flag = args.iter().any(|a| a == "--trace");
31	    let mut svg_out = SvgOut::new(flag("--svg-out").map(PathBuf::from));
32	    if let Some(dir) = flag("--data-dir") {
33	        env.set_data_dir(PathBuf::from(dir));
34	    }
35	    if let Some(dir) = flag("--exp-dir") {
36	        env.set_exp_dir(PathBuf::from(dir));
37	    }
38	    if let Some(path) = flag("-f").or_else(|| flag("--file")) {
39	        let content = std::fs::read_to_string(&path).unwrap_or_else(|e| {
40	            eprintln!("error reading {path}: {e}");
41	            std::process::exit(1);
42	        });
43	        run_script(&content, &mut env, trace_flag, &mut svg_out);
44	    } else {
45	        run_interactive(&mut env, &mut svg_out);
46	    }
47	}
48	
49	fn run_interactive(env: &mut Environment, svg_out: &mut SvgOut) {
50	    println!("{}", version::banner());
51	    println!("Type :help for commands, exit or Ctrl-D to quit.");
52	    println!();
53	
54	    let stdin = io::stdin();
55	    let mut stdout = io::stdout();
56	    let mut tracing = false;
57	    let mut last_trace: Option<Trace> = None;
58	
59	    loop {
60	        print!("mlpl> ");
61	        stdout.flush().unwrap();
62	
63	        let mut line = String::new();
64	        if stdin.lock().read_line(&mut line).unwrap() == 0 {
65	            println!();
66	            break;
67	        }
68	
69	        let trimmed = line.trim();
70	        if trimmed.is_empty() {
71	            continue;
72	        }
73	        if trimmed == "exit" {
74	            break;
75	        }
76	
77	        if handle_command(trimmed, &mut tracing, &last_trace, env) {
78	            continue;
79	        }
80	
81	        eval_line(trimmed, env, tracing, &mut last_trace, svg_out);
82	    }
83	}
84	
85	fn run_script(content: &str, env: &mut Environment, tracing: bool, svg_out: &mut SvgOut) {
86	    // Strip comment-only lines but preserve structure for multi-line constructs
