1	//! Saga 21 step 002: integration tests for the
2	//! `mlpl-repl --connect <url>` client. Spin
3	//! `mlpl-serve` up in-process via
4	//! `mlpl_serve::server::build_app(...)` on a random
5	//! localhost port, then drive the client through
6	//! its public HTTP helpers (`create_session`,
7	//! `eval_remote`, `inspect_remote`). The full
8	//! interactive `read_loop` is hard to drive
9	//! programmatically (stdin), so the tests focus on
10	//! the HTTP layer.
11	//!
12	//! The `connect` module lives inside the
13	//! `mlpl-repl` binary, so the integration test
14	//! includes its source via `#[path = "..."]`.
15	
16	// `connect.rs` lives inside the `mlpl-repl` binary;
17	// re-include it here so the integration test can call
18	// the public helpers directly. The binary uses every
19	// item; the test only exercises a subset, so suppress
20	// dead_code in this compilation unit.
21	#[allow(dead_code)]
22	#[path = "../src/connect.rs"]
23	mod connect;
24	
25	use std::net::SocketAddr;
26	
27	use mlpl_serve::auth::AuthMode;
28	use mlpl_serve::server::build_app;
29	
30	async fn start_server() -> SocketAddr {
31	    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
32	    let addr = listener.local_addr().unwrap();
33	    let app = build_app(AuthMode::Required);
34	    tokio::spawn(async move {
35	        axum::serve(listener, app).await.unwrap();
36	    });
37	    addr
38	}
39	
40	fn blocking_client() -> reqwest::blocking::Client {
41	    reqwest::blocking::Client::builder()
42	        .timeout(std::time::Duration::from_secs(10))
43	        .build()
44	        .unwrap()
45	}
46	
47	#[tokio::test(flavor = "multi_thread")]
48	async fn connect_create_and_eval() {
49	    let addr = start_server().await;
50	    let base = format!("http://{addr}");
51	
52	    let result = tokio::task::spawn_blocking(move || {
53	        let client = blocking_client();
54	        let (id, token) = connect::create_session(&client, &base).unwrap();
55	        assert!(!id.is_empty());
56	        assert!(!token.is_empty());
57	
58	        // Eval a couple of programs against the remote
59	        // session; assert the values come back.
60	        let r1 = connect::eval_remote(&client, &base, &id, &token, "iota(5)").unwrap();
61	        assert_eq!(r1.kind, "array");
62	        assert!(
63	            r1.value.contains('4'),
64	            "iota(5) should contain digit 4: {}",
65	            r1.value
66	        );
67	
68	        // State persists.
69	        connect::eval_remote(&client, &base, &id, &token, "x = 9").unwrap();
70	        let r3 = connect::eval_remote(&client, &base, &id, &token, "x").unwrap();
71	        assert!(
72	            r3.value.contains('9'),
73	            "x should be 9 after assignment: {}",
74	            r3.value
75	        );
76	    })
77	    .await;
78	    result.unwrap();
79	}
80	
81	#[tokio::test(flavor = "multi_thread")]
82	async fn connect_eval_error_returns_server_error() {
83	    let addr = start_server().await;
84	    let base = format!("http://{addr}");
85	
86	    let result = tokio::task::spawn_blocking(move || {
87	        let client = blocking_client();
88	        let (id, token) = connect::create_session(&client, &base).unwrap();
89	
90	        let err = connect::eval_remote(&client, &base, &id, &token, "undefined_var")
91	            .expect_err("expected eval error");
92	        match err {
93	            connect::ClientError::Server { status, message } => {
94	                assert_eq!(status, 400, "eval error should be 400");
95	                assert!(
96	                    message.to_lowercase().contains("undefined")
97	                        || message.contains("undefined_var"),
98	                    "error message should reference the missing variable: {message}"
99	                );
100	            }
101	            other => panic!("expected Server error, got {other:?}"),
102	        }
103	    })
104	    .await;
105	    result.unwrap();
106	}
107	
108	#[tokio::test(flavor = "multi_thread")]
109	async fn connect_inspect_returns_workspace_snapshot() {
110	    let addr = start_server().await;
111	    let base = format!("http://{addr}");
112	
113	    let result = tokio::task::spawn_blocking(move || {
114	        let client = blocking_client();
115	        let (id, token) = connect::create_session(&client, &base).unwrap();
116	
117	        // Bind some state on the remote.
118	        connect::eval_remote(&client, &base, &id, &token, "a = iota(3)").unwrap();
119	        connect::eval_remote(&client, &base, &id, &token, "b = reshape(iota(6), [2, 3])").unwrap();
120	        connect::eval_remote(&client, &base, &id, &token, "m = linear(2, 3, 0)").unwrap();
121	
122	        let snap = connect::inspect_remote(&client, &base, &id, &token).unwrap();
123	        let var_names: Vec<&str> = snap.vars.iter().map(|v| v.name.as_str()).collect();
124	        assert!(
125	            var_names.contains(&"a"),
126	            "a should be in vars: {var_names:?}"
127	        );
128	        assert!(
129	            var_names.contains(&"b"),
130	            "b should be in vars: {var_names:?}"
131	        );
132	        assert!(
133	            snap.models.contains(&"m".to_string()),
134	            "m should be in models: {:?}",
135	            snap.models
136	        );
137	        assert_eq!(snap.more, 0, "no truncation expected");
138	    })
139	    .await;
140	    result.unwrap();
141	}
142	
143	#[tokio::test(flavor = "multi_thread")]
144	async fn connect_session_create_fails_when_server_down() {
145	    // Bind a port, immediately drop the listener, then
146	    // try to create a session against it. The OS will
147	    // reuse the port slot but nothing is listening --
148	    // the connect call should fail with a Network
149	    // error rather than panic.
150	    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
151	    let addr = listener.local_addr().unwrap();
152	    drop(listener);
153	    let base = format!("http://{addr}");
154	
155	    let result = tokio::task::spawn_blocking(move || {
156	        let client = blocking_client();
157	        let err = connect::create_session(&client, &base).expect_err("expected network error");
158	        assert!(matches!(err, connect::ClientError::Network(_)));
159	    })
160	    .await;
161	    result.unwrap();
162	}
