                kind: d.kind,
            }))
        }
        "error" => {
            let e: ErrorData = serde_json::from_str(&data)
                .map_err(|e| ClientError::Network(format!("decode error: {e}")))?;
            Err(ClientError::Server {
                status: 400,
                message: e.error,
            })
        }
        _ => Ok(None),
    }
}

