1	//! Saga 21.5 step 002: streaming `--connect` mode.
2	//!
3	//! Two responsibilities live here so the crate stays at
4	//! its sw-checklist module budget:
5	//!
6	//! 1. Connect-mode argv + env-var parsing
7	//!    (`parse_connect_args`). Pure function so the
8	//!    integration tests can drive it without a
9	//!    subprocess.
10	//! 2. The SSE wire path (`eval_remote_stream`) plus the
11	//!    per-iteration progress display (`render_metric`).
12	//!    Pure transport -- the REPL loop that calls into
13	//!    these lives in `connect_repl.rs`.
14	//!
15	//! Why pure-fn parsing: the binary's wrapper translates
16	//! `Err` into `std::process::exit(2)`, but the test
17	//! suite needs to assert the exit reason without forking
18	//! a subprocess.
19	
20	use std::io::{self, BufRead, BufReader, Write};
21	
22	use serde::Deserialize;
23	
24	use crate::connect::{ClientError, EvalResponse};
25	
26	/// Three connect-mode invocation shapes the binary
27	/// distinguishes after argv + env-var parsing. `Local`
28	/// means "no `--connect` flag, fall through to local
29	/// REPL"; `Remote` is connect mode with the streaming
30	/// flag baked in.
31	#[derive(Debug)]
32	pub enum ConnectMode {
33	    Local,
34	    Remote { url: String, stream: bool },
35	}
36	
37	/// Parser errors that the binary maps to `exit(2)` with
38	/// a usage hint. Kept enum-shaped (rather than `String`)
39	/// so tests can match on variants without coupling to
40	/// the exact wording of the message.
41	#[derive(Debug)]
42	pub enum ConnectArgsError {
43	    StreamWithoutConnect,
44	    LocalFlagWithConnect(String),
45	}
46	
47	/// One `event: metric` frame off the SSE stream. The
48	/// streaming client surfaces these to its caller via a
49	/// `FnMut(&SseMetric)` callback so the REPL can render
50	/// one progress line per iteration while the eval is
51	/// still running on the server.
52	#[derive(Debug, Clone)]
53	pub struct SseMetric {
54	    pub name: String,
55	    pub step: usize,
56	    pub value: f64,
57	}
58	
59	const LOCAL_ONLY_FLAGS: &[&str] = &["-f", "--file", "--data-dir", "--exp-dir"];
60	
61	/// Parse the connect-mode shape from argv plus the
62	/// `MLPL_REPL_STREAM` env var. Pure function: the binary
63	/// reads the env var itself and passes it in; tests can
64	/// vary it freely. Falsy values (`0`, empty, `false`,
65	/// `no`, `off`, case-insensitive) explicitly disable
66	/// streaming so a stale `export` in a user's shell does
67	/// not silently change behavior.
68	pub fn parse_connect_args(
69	    args: &[String],
70	    stream_env: Option<&str>,
71	) -> Result<ConnectMode, ConnectArgsError> {
72	    let connect_url = args
73	        .iter()
74	        .position(|a| a == "--connect")
75	        .and_then(|p| args.get(p + 1))
76	        .cloned();
77	    let stream = args.iter().any(|a| a == "--stream") || env_is_truthy(stream_env);
78	    match connect_url {
79	        None if stream => Err(ConnectArgsError::StreamWithoutConnect),
80	        None => Ok(ConnectMode::Local),
81	        Some(url) => {
82	            if let Some(bad) = args.iter().find(|a| LOCAL_ONLY_FLAGS.contains(&a.as_str())) {
83	                return Err(ConnectArgsError::LocalFlagWithConnect(bad.clone()));
84	            }
85	            Ok(ConnectMode::Remote { url, stream })
86	        }
87	    }
88	}
89	
90	fn env_is_truthy(v: Option<&str>) -> bool {
91	    match v {
92	        None => false,
93	        Some(s) => {
94	            let lower = s.trim().to_ascii_lowercase();
95	            !lower.is_empty() && lower != "0" && lower != "false" && lower != "no" && lower != "off"
96	        }
97	    }
98	}
99	
100	/// Render one `metric` frame as a progress line. Uses
101	/// `\r` (no newline) so successive frames overwrite the
102	/// same terminal row -- the REPL wrapper writes a
103	/// trailing `\n` after the eval completes so the result
104	/// lands on its own line. Test callers compare on
105	/// substrings.
106	pub fn render_metric<W: Write>(out: &mut W, m: &SseMetric) -> io::Result<()> {
107	    write!(out, "  [step {}] {} = {:.6}\r", m.step, m.name, m.value)?;
108	    out.flush()
109	}
110	
111	#[derive(Deserialize)]
112	struct MetricData {
113	    name: String,
114	    step: usize,
115	    value: f64,
116	}
117	
118	#[derive(Deserialize)]
119	struct DoneData {
120	    value: String,
121	    kind: String,
122	}
123	
124	#[derive(Deserialize)]
125	struct ErrorData {
126	    error: String,
127	}
128	
129	/// POST `/v1/sessions/<id>/eval_stream` and consume the
130	/// SSE body line-by-line. `on_metric` fires once per
131	/// `event: metric` frame; the function returns when the
132	/// stream emits a terminal `event: done` (Ok) or
133	/// `event: error` (Err with `ClientError::Server` mapped
134	/// to HTTP 400 to match the non-streaming `/eval` error
135	/// taxonomy). Transport-level failures map to
136	/// `ClientError::Network`.
137	pub fn eval_remote_stream(
138	    client: &reqwest::blocking::Client,
139	    base_url: &str,
140	    session_id: &str,
141	    token: &str,
142	    program: &str,
143	    on_metric: &mut dyn FnMut(&SseMetric),
144	) -> Result<EvalResponse, ClientError> {
145	    let resp = client
146	        .post(format!(
147	            "{}/v1/sessions/{session_id}/eval_stream",
148	            base_url.trim_end_matches('/')
149	        ))
150	        .bearer_auth(token)
151	        .json(&serde_json::json!({"program": program}))
152	        .send()
153	        .map_err(|e| ClientError::Network(e.to_string()))?;
154	    if !resp.status().is_success() {
155	        let status = resp.status().as_u16();
156	        let body = resp.text().unwrap_or_default();
157	        let message = serde_json::from_str::<serde_json::Value>(&body)
158	            .ok()
159	            .and_then(|v| v.get("error").and_then(|e| e.as_str()).map(str::to_string))
160	            .unwrap_or(body);
161	        return Err(ClientError::Server { status, message });
162	    }
163	    consume_sse_stream(BufReader::new(resp), on_metric)
164	}
165	
166	/// Consume the framed SSE body. Separated from
167	/// `eval_remote_stream` so the wire setup and the parser
168	/// each stay under the sw-checklist 25-line LOC warning
169	/// budget.
170	fn consume_sse_stream<R: BufRead>(
171	    reader: R,
172	    on_metric: &mut dyn FnMut(&SseMetric),
173	) -> Result<EvalResponse, ClientError> {
174	    let mut event: Option<String> = None;
175	    let mut data: Option<String> = None;
176	    for line in reader.lines() {
177	        let line = line.map_err(|e| ClientError::Network(format!("stream read: {e}")))?;
178	        if line.is_empty() {
179	            if let Some(outcome) = handle_frame(event.take(), data.take(), on_metric)? {
180	                return Ok(outcome);
181	            }
182	        } else if let Some(rest) = line.strip_prefix("event:") {
183	            event = Some(rest.trim().to_string());
184	        } else if let Some(rest) = line.strip_prefix("data:") {
185	            data = Some(rest.trim().to_string());
186	        }
187	    }
188	    Err(ClientError::Network(
189	        "stream ended without done/error".into(),
190	    ))
191	}
192	
193	/// Dispatch one assembled SSE frame. `Ok(Some(_))` means
194	/// terminal (`done` -> return to caller); `Ok(None)`
195	/// means continue reading (`ready` / `metric`); `Err`
196	/// means terminal-error (the server sent `event: error`
197	/// or the payload failed to parse).
198	fn handle_frame(
199	    event: Option<String>,
200	    data: Option<String>,
201	    on_metric: &mut dyn FnMut(&SseMetric),
202	) -> Result<Option<EvalResponse>, ClientError> {
203	    let (Some(event), Some(data)) = (event, data) else {
204	        return Ok(None);
205	    };
206	    match event.as_str() {
207	        "ready" => Ok(None),
208	        "metric" => {
209	            let m: MetricData = serde_json::from_str(&data)
210	                .map_err(|e| ClientError::Network(format!("decode metric: {e}")))?;
211	            on_metric(&SseMetric {
212	                name: m.name,
213	                step: m.step,
214	                value: m.value,
215	            });
216	            Ok(None)
217	        }
218	        "done" => {

