87	/// `train N { loss_metric = ... }` produces one
88	/// `event: metric` frame per iteration. The streaming
89	/// client surfaces each as a callback with the correct
90	/// `(name, step, value)` triple.
91	#[tokio::test(flavor = "multi_thread")]
92	async fn stream_emits_one_metric_per_train_iteration() {
93	    let addr = start_server().await;
94	    let base = format!("http://{addr}");
95	
96	    let result = tokio::task::spawn_blocking(move || {
97	        let client = blocking_client();
98	        let (id, token) = connect::create_session(&client, &base).unwrap();
99	
100	        let mut frames: Vec<(String, usize, f64)> = Vec::new();
101	        let resp = connect_stream::eval_remote_stream(
102	            &client,
103	            &base,
104	            &id,
105	            &token,
106	            "train 5 { loss_metric = step + 0.5 }",
107	            &mut |m| frames.push((m.name.clone(), m.step, m.value)),
108	        )
109	        .unwrap();
110	
111	        assert_eq!(
112	            frames.len(),
113	            5,
114	            "expected 5 metric frames, got {} ({frames:?})",
115	            frames.len()
116	        );
117	        for (i, (name, step, value)) in frames.iter().enumerate() {
118	            assert_eq!(name, "loss_metric", "frame {i}: wrong name");
119	            assert_eq!(*step, i, "frame {i}: wrong step");
120	            let expected = i as f64 + 0.5;
121	            assert!(
122	                (*value - expected).abs() < 1e-9,
123	                "frame {i}: value {value} != {expected}"
124	            );
125	        }
126	        // Final value is the last `step_val` from the
127	        // train body -- here `step + 0.5` at step=4, so
128	        // 4.5. The server tags every `DenseArray` (even
129	        // rank-0 scalars) as `kind = "array"`.
130	        assert_eq!(resp.kind, "array");
131	        assert!(
132	            resp.value.contains("4.5"),
133	            "final value should be 4.5: {}",
134	            resp.value
135	        );
136	    })
137	    .await;
138	    result.unwrap();
139	}
